async function onRequest(request, settings) {
  const body = request.json();
  const events = [];
  events.push({
    type: 'track',
    event: body.event || 'Webhook Received',
    userId: body.userId || 'source-fn-anonymous',
    properties: {
      source: 'source_function',
      originalPayload: body,
      apiKey: settings.apiKey || 'not-set'
    },
    context: {
      library: { name: 'source-function', version: '1.0.0' }
    }
  });
  return events;
}

