async function onTrack(event, settings) {
  const endpoint = settings.webhookUrl;
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...event, handlerType: 'onTrack' })
  });
  return response;
}

