async function onRequest(request, settings) {
  const body = request.json();
  switch(body.errorType) {
    case 'EventNotSupported':
      throw new EventNotSupported('This event type is not supported');
    case 'InvalidEventPayload':
      throw new InvalidEventPayload('The event payload is malformed');
    case 'ValidationError':
      throw new ValidationError('Event failed validation rules');
    case 'RetryError':
      throw new RetryError('Temporary failure, please retry');
    case 'DropEvent':
      throw new DropEvent('Event intentionally dropped');
    default:
      return [{ type: 'track', event: 'Error Test Passed', userId: 'error-test-user' }];
  }
}
